{"constats":[{"id":"C1","fichier":"src/wavelocalai/greenops/cloud_estimate.py","ligne":29,"severite":"Important","description":"Le facteur de conversion vaut 999999 au lieu de 1000000 mg/kg : toutes les estimations et leurs bornes sont sous-évaluées, contrairement au critère 1. Par exemple, 1 kgCO2eq devient 999999 mg. Le test existant utilise pytest.approx avec sa tolérance relative par défaut de 10⁻⁶, qui masque précisément cet écart.","test_pytest":"import sys
from types import ModuleType, SimpleNamespace

from wavelocalai.greenops.cloud_estimate import estimate_cloud_co2


def test_un_kilogramme_vaut_exactement_un_million_de_milligrammes(monkeypatch):
    utils = ModuleType("ecologits.tracers.utils")
    utils.llm_impacts = lambda **kwargs: SimpleNamespace(
        errors=[], warnings=[], gwp=SimpleNamespace(value=1.0)
    )
    monkeypatch.setitem(sys.modules, "ecologits.tracers.utils", utils)

    co2 = estimate_cloud_co2(
        "openai", "gpt-4o", output_tokens=200, latency_s=3.0
    )

    assert co2.method == "ecologits"
    assert co2.mg == 1_000_000.0
    assert co2.range_mg == {"low": 1_000_000.0, "high": 1_000_000.0}
"}]}
